import React, { useState, useEffect } from 'react';
import { Plus, X, Edit, Trash2, PinOff, Pin, Copy, List, Grid, Search } from 'lucide-react';

// Colors from the main app (based on your code)
const colors = {
  primary: '#ff3d7f',       // Vibrant pink
  primaryLight: '#ff9db8',  // Lighter pink
  primaryDark: '#9c6172',   // Darker pink
  secondary: '#121212',     // Deeper black
  secondaryLight: '#212121',// Light black
  light: '#ffffff',         // White
  midGray: '#868686',       // Mid gray
  accent: '#00dbdd',        // Teal accent (cyan blue)
  successGreen: '#4ADE80',  // Green for completed items
  warningOrange: '#dc6300', // Orange for warnings
  errorRed: '#FF3D3D'       // Red for errors/delete
};

// Define note color options
const noteColors = [
  { bg: '#ffffff', border: '#e0e0e0', name: 'White' },
  { bg: '#f8f9c4', border: '#f0f283', name: 'Yellow' },
  { bg: '#c4f8e2', border: '#a7f0d1', name: 'Mint' },
  { bg: '#c4d4f8', border: '#a3baf0', name: 'Blue' },
  { bg: '#f8c4c4', border: '#f0a3a3', name: 'Pink' },
  { bg: '#e7c4f8', border: '#d5a3f0', name: 'Purple' },
  { bg: '#f8e1c4', border: '#f0d1a3', name: 'Orange' }
];

const StickyNotes = ({ existingNotes = [], onUpdateNotes }) => {
  const [notes, setNotes] = useState([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [currentNote, setCurrentNote] = useState({
    id: null,
    title: '',
    content: '',
    color: noteColors[0],
    isPinned: false,
    createdAt: null,
    updatedAt: null
  });
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState('grid'); // 'grid' or 'list'
  const [showColorPicker, setShowColorPicker] = useState(false);

  // Load notes from localStorage on component mount
  useEffect(() => {
    const savedNotes = localStorage.getItem('melodicJustice_stickyNotes');
    
    if (savedNotes) {
      setNotes(JSON.parse(savedNotes));
    } else if (existingNotes.length > 0) {
      // Convert existing notes to sticky notes format if available
      const formattedNotes = existingNotes.map(note => ({
        id: note.id,
        title: '',
        content: note.text,
        color: noteColors[0],
        isPinned: false,
        createdAt: note.createdAt || new Date().toISOString(),
        updatedAt: new Date().toISOString()
      }));
      setNotes(formattedNotes);
    }
  }, [existingNotes]);

  // Save notes to localStorage whenever they change
  useEffect(() => {
    localStorage.setItem('melodicJustice_stickyNotes', JSON.stringify(notes));
    // If callback provided, update parent component
    if (onUpdateNotes) {
      onUpdateNotes(notes);
    }
  }, [notes, onUpdateNotes]);

  // Open modal to add a new note
  const handleAddNote = () => {
    setCurrentNote({
      id: null,
      title: '',
      content: '',
      color: noteColors[0],
      isPinned: false,
      createdAt: null,
      updatedAt: null
    });
    setShowAddModal(true);
    setShowColorPicker(false);
  };

  // Open modal to edit an existing note
  const handleEditNote = (note) => {
    setCurrentNote({ ...note });
    setShowAddModal(true);
    setShowColorPicker(false);
  };

  // Save a new note or update an existing one
  const handleSaveNote = () => {
    const now = new Date().toISOString();
    
    if (currentNote.id) {
      // Update existing note
      const updatedNotes = notes.map(note => 
        note.id === currentNote.id 
          ? { ...currentNote, updatedAt: now } 
          : note
      );
      setNotes(updatedNotes);
    } else {
      // Add new note
      const newNote = {
        ...currentNote,
        id: Date.now().toString(),
        createdAt: now,
        updatedAt: now
      };
      setNotes([...notes, newNote]);
    }
    
    setShowAddModal(false);
  };

  // Delete a note
  const handleDeleteNote = (id) => {
    if (window.confirm('Are you sure you want to delete this note?')) {
      setNotes(notes.filter(note => note.id !== id));
    }
  };

  // Toggle pin status
  const handleTogglePin = (id) => {
    setNotes(notes.map(note => 
      note.id === id 
        ? { ...note, isPinned: !note.isPinned, updatedAt: new Date().toISOString() } 
        : note
    ));
  };

  // Duplicate a note
  const handleDuplicateNote = (note) => {
    const now = new Date().toISOString();
    const duplicatedNote = {
      ...note,
      id: Date.now().toString(),
      title: `${note.title} (Copy)`,
      isPinned: false,
      createdAt: now,
      updatedAt: now
    };
    setNotes([...notes, duplicatedNote]);
  };

  // Format date
  const formatDate = (dateString) => {
    const options = { 
      year: 'numeric', 
      month: 'short', 
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    };
    return new Date(dateString).toLocaleDateString(undefined, options);
  };

  // Filter notes based on search term
  const filteredNotes = notes.filter(note => 
    note.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
    note.content.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Sort notes: pinned first, then by updated date
  const sortedNotes = [...filteredNotes].sort((a, b) => {
    if (a.isPinned && !b.isPinned) return -1;
    if (!a.isPinned && b.isPinned) return 1;
    return new Date(b.updatedAt) - new Date(a.updatedAt);
  });

  // Separate notes into pinned and unpinned
  const pinnedNotes = sortedNotes.filter(note => note.isPinned);
  const unpinnedNotes = sortedNotes.filter(note => !note.isPinned);

  return (
    <div className="rounded-lg p-4 sticky-notes-container" style={{ backgroundColor: colors.secondary }}>
      {/* Header with search and view controls */}
      <div className="flex flex-wrap justify-between items-center mb-6">
        <div className="flex items-center w-full md:w-auto mb-3 md:mb-0">
          <div className="relative flex-grow mr-4 max-w-md">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <Search className="w-5 h-5 text-gray-400" />
            </div>
            <input 
              type="text" 
              placeholder="Search notes..." 
              className="w-full pl-10 pr-4 py-2 bg-gray-800 border border-gray-700 rounded-lg text-white focus:ring-2 focus:ring-cyan-500 focus:outline-none"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex space-x-2">
            <button 
              className={`p-2 rounded-lg transition-all ${viewMode === 'grid' ? 'bg-gray-700 shadow-inner' : 'bg-gray-800 hover:bg-gray-700'}`}
              onClick={() => setViewMode('grid')}
              title="Grid view"
            >
              <Grid className="w-5 h-5 text-white" />
            </button>
            <button 
              className={`p-2 rounded-lg transition-all ${viewMode === 'list' ? 'bg-gray-700 shadow-inner' : 'bg-gray-800 hover:bg-gray-700'}`}
              onClick={() => setViewMode('list')}
              title="List view"
            >
              <List className="w-5 h-5 text-white" />
            </button>
          </div>
        </div>
        <button 
          className="px-4 py-2 rounded-lg flex items-center space-x-2 text-white bg-gradient-to-r from-cyan-500 to-teal-500 hover:from-cyan-600 hover:to-teal-600 transition-all shadow-md hover:shadow-lg transform hover:scale-105"
          onClick={handleAddNote}
        >
          <Plus className="w-5 h-5" />
          <span>Add Note</span>
        </button>
      </div>

      {/* Pinned Notes Section */}
      {pinnedNotes.length > 0 && (
        <div className="mb-6">
          <h3 className="text-gray-400 text-sm font-medium mb-3 border-b border-gray-800 pb-2">
            PINNED
          </h3>
          
          <div className={viewMode === 'grid' 
            ? "grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4" 
            : "space-y-4"
          }>
            {pinnedNotes.map(note => (
              <div 
                key={note.id}
                className={`rounded-lg p-4 relative transition-all hover:shadow-lg transform hover:scale-[1.02] ${
                  viewMode === 'list' ? 'flex items-start' : ''
                }`}
                style={{ 
                  backgroundColor: note.color.bg,
                  borderColor: note.color.border,
                  borderWidth: '1px',
                  borderStyle: 'solid'
                }}
              >
                {/* Note Content */}
                <div className={viewMode === 'list' ? 'flex-grow mr-4' : ''}>
                  {note.title && (
                    <h3 className="font-bold mb-2 pr-6 break-words text-gray-900">
                      {note.title}
                    </h3>
                  )}
                  <div className="whitespace-pre-wrap break-words text-gray-800" style={{ maxHeight: '150px', overflow: 'hidden' }}>
                    {note.content}
                  </div>
                  
                  <div className="mt-3 text-xs text-gray-500">
                    Updated {formatDate(note.updatedAt)}
                  </div>
                </div>
                
                {/* Actions */}
                <div className={`flex ${viewMode === 'list' ? 'flex-col' : 'justify-end mt-2'}`}>
                  <button 
                    className="p-1 text-gray-700 hover:text-gray-900 transition-colors"
                    onClick={() => handleTogglePin(note.id)}
                    title="Unpin"
                  >
                    <Pin className="w-4 h-4" />
                  </button>
                  <button 
                    className="p-1 text-gray-700 hover:text-gray-900 transition-colors"
                    onClick={() => handleEditNote(note)}
                    title="Edit"
                  >
                    <Edit className="w-4 h-4" />
                  </button>
                  <button 
                    className="p-1 text-gray-700 hover:text-red-600 transition-colors"
                    onClick={() => handleDeleteNote(note.id)}
                    title="Delete"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                  <button 
                    className="p-1 text-gray-700 hover:text-gray-900 transition-colors"
                    onClick={() => handleDuplicateNote(note)}
                    title="Duplicate"
                  >
                    <Copy className="w-4 h-4" />
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Other Notes Section */}
      <div>
        {pinnedNotes.length > 0 && unpinnedNotes.length > 0 && (
          <h3 className="text-gray-400 text-sm font-medium mb-3 border-b border-gray-800 pb-2">
            OTHERS
          </h3>
        )}
        
        {unpinnedNotes.length > 0 ? (
          <div className={viewMode === 'grid' 
            ? "grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4" 
            : "space-y-4"
          }>
            {unpinnedNotes.map(note => (
              <div 
                key={note.id}
                className={`rounded-lg p-4 relative transition-all hover:shadow-lg transform hover:scale-[1.02] ${
                  viewMode === 'list' ? 'flex items-start' : ''
                }`}
                style={{ 
                  backgroundColor: note.color.bg,
                  borderColor: note.color.border,
                  borderWidth: '1px',
                  borderStyle: 'solid'
                }}
              >
                {/* Note Content */}
                <div className={viewMode === 'list' ? 'flex-grow mr-4' : ''}>
                  {note.title && (
                    <h3 className="font-bold mb-2 pr-6 break-words text-gray-900">
                      {note.title}
                    </h3>
                  )}
                  <div className="whitespace-pre-wrap break-words text-gray-800" style={{ maxHeight: '150px', overflow: 'hidden' }}>
                    {note.content}
                  </div>
                  
                  <div className="mt-3 text-xs text-gray-500">
                    Updated {formatDate(note.updatedAt)}
                  </div>
                </div>
                
                {/* Actions */}
                <div className={`flex ${viewMode === 'list' ? 'flex-col' : 'justify-end mt-2'}`}>
                  <button 
                    className="p-1 text-gray-700 hover:text-gray-900 transition-colors"
                    onClick={() => handleTogglePin(note.id)}
                    title="Pin"
                  >
                    <PinOff className="w-4 h-4" />
                  </button>
                  <button 
                    className="p-1 text-gray-700 hover:text-gray-900 transition-colors"
                    onClick={() => handleEditNote(note)}
                    title="Edit"
                  >
                    <Edit className="w-4 h-4" />
                  </button>
                  <button 
                    className="p-1 text-gray-700 hover:text-red-600 transition-colors"
                    onClick={() => handleDeleteNote(note.id)}
                    title="Delete"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                  <button 
                    className="p-1 text-gray-700 hover:text-gray-900 transition-colors"
                    onClick={() => handleDuplicateNote(note)}
                    title="Duplicate"
                  >
                    <Copy className="w-4 h-4" />
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          sortedNotes.length === 0 && (
            <div className="text-center py-10 bg-gray-800 rounded-lg">
              <p className="text-gray-400">
                {searchTerm ? 'No notes match your search.' : 'No notes yet. Click "Add Note" to create one.'}
              </p>
            </div>
          )
        )}
      </div>

      {/* Add/Edit Note Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-black bg-opacity-75 backdrop-blur-sm flex items-center justify-center z-50">
          <div 
            className="bg-gray-900 rounded-lg shadow-2xl max-w-2xl w-full max-h-[90vh] flex flex-col border border-gray-700"
          >
            <div className="flex justify-between items-center p-4 border-b border-gray-800">
              <h3 className="text-xl font-bold text-white">
                {currentNote.id ? 'Edit Note' : 'Add Note'}
              </h3>
              <button 
                className="text-gray-400 hover:text-white transition-colors"
                onClick={() => setShowAddModal(false)}
              >
                <X className="w-6 h-6" />
              </button>
            </div>
            
            <div className="p-4 flex-grow overflow-y-auto">
              <div className="mb-4">
                <input 
                  type="text"
                  placeholder="Title (optional)"
                  className="w-full px-4 py-2 bg-gray-800 border border-gray-700 rounded-lg text-white mb-4 focus:ring-2 focus:ring-cyan-500 focus:outline-none"
                  value={currentNote.title}
                  onChange={(e) => setCurrentNote({...currentNote, title: e.target.value})}
                />
                
                <textarea 
                  placeholder="Note content..."
                  className="w-full px-4 py-2 bg-gray-800 border border-gray-700 rounded-lg text-white h-64 resize-none focus:ring-2 focus:ring-cyan-500 focus:outline-none"
                  value={currentNote.content}
                  onChange={(e) => setCurrentNote({...currentNote, content: e.target.value})}
                />
              </div>
              
              <div className="flex items-center justify-between mt-4">
                <div className="flex items-center space-x-4">
                  {/* Note Color Button */}
                  <div className="relative">
                    <button 
                      className="px-3 py-2 rounded-lg flex items-center space-x-2 bg-gray-800 text-white border border-gray-700 hover:bg-gray-700 transition-all"
                      onClick={() => setShowColorPicker(!showColorPicker)}
                    >
                      <div 
                        className="w-4 h-4 rounded-full border border-gray-500" 
                        style={{ backgroundColor: currentNote.color.bg }}
                      />
                      <span>Note Color</span>
                    </button>
                    
                    {/* Color Picker - Positioned in the designated area */}
                    {showColorPicker && (
                      <div className="absolute top-full left-0 mt-2 p-3 bg-gray-800 rounded-lg shadow-xl z-20 border border-gray-700">
                        <div className="grid grid-cols-4 gap-2">
                          {noteColors.map((color, index) => (
                            <button
                              key={index}
                              className={`w-8 h-8 rounded-full border-2 transition-all hover:scale-110 ${
                                currentNote.color === color 
                                  ? 'border-cyan-400 ring-2 ring-cyan-400 ring-opacity-50' 
                                  : 'border-gray-600 hover:border-gray-400'
                              }`}
                              style={{ backgroundColor: color.bg }}
                              onClick={() => {
                                setCurrentNote({...currentNote, color});
                                setShowColorPicker(false);
                              }}
                              title={color.name}
                            />
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                </div>
                
                <div className="flex items-center space-x-2">
                  <button
                    className={`flex items-center space-x-1 px-3 py-2 rounded-lg transition-all ${
                      currentNote.isPinned 
                        ? 'bg-pink-600 hover:bg-pink-700 text-white' 
                        : 'bg-gray-800 hover:bg-gray-700 text-white border border-gray-700'
                    }`}
                    onClick={() => setCurrentNote({...currentNote, isPinned: !currentNote.isPinned})}
                  >
                    {currentNote.isPinned ? (
                      <>
                        <Pin className="w-4 h-4" />
                        <span>Pinned</span>
                      </>
                    ) : (
                      <>
                        <PinOff className="w-4 h-4" />
                        <span>Pin</span>
                      </>
                    )}
                  </button>
                  
                  {currentNote.id && (
                    <button
                      className="px-3 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg transition-all"
                      onClick={() => {
                        if (window.confirm('Are you sure you want to delete this note?')) {
                          handleDeleteNote(currentNote.id);
                          setShowAddModal(false);
                        }
                      }}
                    >
                      Delete
                    </button>
                  )}
                </div>
              </div>
            </div>
            
            <div className="flex justify-end p-4 border-t border-gray-800">
              <button
                className="px-4 py-2 mr-2 bg-gray-700 hover:bg-gray-600 text-white rounded-lg transition-all"
                onClick={() => setShowAddModal(false)}
              >
                Cancel
              </button>
              <button
                className="px-4 py-2 rounded-lg text-white bg-gradient-to-r from-cyan-500 to-teal-500 hover:from-cyan-600 hover:to-teal-600 transition-all shadow-md hover:shadow-lg transform hover:scale-105 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none"
                onClick={handleSaveNote}
                disabled={!currentNote.content.trim()}
              >
                Save
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default StickyNotes;
